[-6.917028,107.642854],[-6.916963,107.642923],[-6.916891,107.642988],[-6.916813,107.643047],[-6.91673,107.643099],[-6.916643,107.643146],[-6.916551,107.643186],[-6.916456,107.643218],[-6.916358,107.643244],[-6.916259,107.643262]],"sources":[{"label":"Google Maps — Kiara Artha Park & tempat di sekitarnya","url":"https://maps.google.com/?q=-6.9164043,107.642318","accessed":"2026-11-16"},{"label":"detikJabar — Kiara Artha Park, Spot Rekreasi di Tengah Kota Bandung","url":"https://www.detik.com/jabar/wisata/d-7229191/kiara-artha-park-spot-rekreasi-di-tengah-kota-bandung"},{"label":"Orami — Kiara Artha Park (30 Sep 2024)","url":"https://www.orami.co.id/magazine/kiara-artha-park"},{"label":"Republika — Ayo Intip Keseruan di Kiara Artha Park (24 Agu 2019)","url":"https://news.republika.co.id/berita/pwoiiv0/ayo-intip-keseruan-di-kiara-artha-park-bandung"},{"label":"Pemkot Bandung — Bike on The Street Everybody Happy (BOSEH)","url":"https://www.bandung.go.id/sub-etalase/27/sepeda"}]}'::jsonb, '2026-11-16')
