-- Trivia (≥1 per POI; is_verified = bersumber dokumen/Google Maps)
delete from public.trivia;
insert into public.trivia (poi_id, content, source_reference, is_verified) values
  ('P01', 'Kiara Artha Park diresmikan pada 17 Agustus 2019, bertepatan dengan HUT ke-74 Republik Indonesia.', 'Orami (30 Sep 2024); Republika (24 Agu 2019)', true),
  ('P01', 'Taman ini terletak di antara flyover Antapani dan flyover Kiaracondong, di Kelurahan Kebonwaru, Kecamatan Batununggal.', 'Orami (2024); Republika (2019)', true),
  ('P02', 'Lokasi taman yang berada di antara dua flyover besar Bandung timur membuatnya mudah dijangkau dari arah Antapani maupun Kiaracondong.', 'Orami (2024); Republika (2019)', true),
  ('P02', 'Tiket masuk taman tercatat Rp10.000 per orang, baik hari kerja maupun akhir pekan (detikJabar, 2024). Cek kembali di loket karena harga dapat berubah.', 'detikJabar (Mar 2024)', true),
  ('P03', 'Pertunjukan air mancur menari umumnya digelar mulai pukul 18.30 hingga 20.30, dengan pertunjukan berbeda setiap jamnya (Orami, 2024).', 'Orami (30 Sep 2024)', true),
  ('P03', 'Patung Friendship Shake Hand di tepi utara danau menggambarkan jabat tangan persahabatan, sejalan dengan semangat Asia Afrika kota Bandung.', 'Google Maps: Friendship Shake Hand Sculpture', true),
  ('P04', 'Kiara Artha Park sempat dipromosikan media sebagai destinasi wisata Bandung ala Korea berkat Kampung Korea-nya (VIVA).', 'VIVA: Kiara Artha Park, Destinasi Wisata Bandung Ala Korea', true),
  ('P04', 'Selain zona Asia, taman ini punya Taman Asia Afrika di sisi selatan danau, yang namanya menggemakan Konferensi Asia Afrika 1955 di Bandung.', 'Google Maps: Taman Asia Afrika - Kiara Artha Park', true),
  ('P05', 'Konferensi Asia Afrika digelar di Gedung Merdeka, Bandung, pada 18–24 April 1955 dan dihadiri 29 negara.', 'Sejarah KAA 1955 (Museum KAA) — perlu dicek tim', false),
  ('P05', 'Dari titik ini air mancur menari terlihat utuh, sudut favorit untuk foto malam.', 'Pengamatan peta Google Maps', true),
  ('P06', 'Area jogging dan bersepeda di Kiara Artha Park disebut mencapai sekitar 2,6 hektare (Orami, 2024).', 'Orami (30 Sep 2024)', true),
  ('P06', 'Kiara Artha Park pernah menjadi tuan rumah acara lari Pocari Run 2025.', 'Asia Property Awards — profil Kiara Artha Park', true),
  ('P07', 'BOSEH adalah program sepeda sewa Pemerintah Kota Bandung; tarif resmi tercatat Rp1.000 untuk jam pertama dan Rp2.000 untuk jam berikutnya.', 'Pemkot Bandung — BOSEH', true),
  ('P07', 'Persewaan sepeda dan skuter listrik di dalam taman bertarif Rp30.000 pada hari kerja dan Rp40.000 pada akhir pekan (detikJabar, 2024).', 'detikJabar (Mar 2024)', true),
  ('P08', 'Paket Kiara Pelangi Food Court seharga Rp35.000 disebut sudah termasuk akses menonton air mancur menari (Orami, 2024).', 'Orami (30 Sep 2024)', true),
  ('P08', 'Ludo Sports Kitchen and Coffee di dekat area ini memiliki lebih dari seribu ulasan di Google Maps dengan rating 4,8.', 'Google Maps: Ludo Sports Kitchen and Coffee (16 Nov 2026)', true),
  ('P09', 'Padel lahir di Acapulco, Meksiko, pada 1969 dan dimainkan berpasangan di lapangan berdinding kaca.', 'Pengetahuan umum olahraga padel — perlu dicek tim', false),
  ('P09', 'Dalam padel, bola boleh memantul ke dinding sebelum dipukul kembali, berbeda dengan tenis.', 'Pengetahuan umum olahraga padel — perlu dicek tim', false),
  ('P10', 'Lollipop Playland termasuk fasilitas yang paling sering disebut media saat membahas Kiara Artha Park, bersama air mancur menari dan Kampung Korea.', 'Ringkasan media (Orami 2024, Republika 2019)', false),
  ('P10', 'Area ini berada sekitar 80 meter dari air mancur, titik temu yang mudah diingat bila anggota keluarga terpisah.', 'Hitungan jarak koordinat Google Maps', true),
  ('P11', 'Kanopi pohon dapat membuat udara di bawahnya terasa lebih sejuk dibanding area terbuka di siang hari.', 'Pengetahuan umum kesehatan — perlu dicek tim', false),
  ('P11', 'Menghembuskan napas lebih panjang daripada menarik napas membantu menenangkan detak jantung setelah berjalan.', 'Pengetahuan umum kesehatan — perlu dicek tim', false),
  ('P12', 'Musala ini tercatat di Google Maps sebagai "Mushalla Kiara Artha Park", berdekatan dengan Layana Hall.', 'Google Maps: Mushalla Kiara Artha Park', true),
  ('P12', 'Toilet umum lain juga tersedia di sekitar area parkir sisi barat laut taman.', 'Google Maps: "Kamar Cai" dekat parkir — perlu dicek tim', false);

