insert into public.trail_checkpoint (trail_id, seq, name, poi_id, location, radius_m, exercise, coaching) values
  ('T01', 1, 'Titik Start Jogging Track', 'P06', extensions.st_setsrid(extensions.st_makepoint(107.6417524, -6.9152676), 4326)::extensions.geography, 25, 'Pemanasan 1 menit', 'Checkpoint satu, titik start. Mari pemanasan. Putar pergelangan kaki kanan dan kiri masing-masing lima kali, lalu ayunkan kedua lengan ke depan dan ke belakang. Setelah itu, mulailah berjalan santai ke arah timur menuju musala.'),
  ('T01', 2, 'Musala & Layana Hall', 'P12', extensions.st_setsrid(extensions.st_makepoint(107.6421597, -6.9151658), 4326)::extensions.geography, 20, 'Cek hidrasi', 'Checkpoint dua, sisi utara taman. Di sini ada musala dan toilet. Jika haus, minumlah beberapa teguk air. Jaga postur: bahu rileks, pandangan ke depan. Lanjutkan ke arah timur menuju zona teduh.'),
  ('T01', 3, 'Zona Teduh', 'P11', extensions.st_setsrid(extensions.st_makepoint(107.643112, -6.91593), 4326)::extensions.geography, 20, 'Peregangan ringan 1 menit', 'Checkpoint tiga, Zona Teduh. Saatnya peregangan ringan satu menit. Tarik lengan kanan menyilang ke depan dada, tahan sepuluh hitungan, lalu ganti lengan kiri. Kemudian tarik napas empat hitungan dan hembuskan enam hitungan. Ulangi tiga kali.'),
  ('T01', 4, 'Taman Asia Afrika', 'P05', extensions.st_setsrid(extensions.st_makepoint(107.6421607, -6.9166173), 4326)::extensions.geography, 25, 'Latihan napas 4-6', 'Checkpoint empat, Taman Asia Afrika. Pandanglah danau dan air mancur di utara. Tarik napas dalam empat hitungan, hembuskan enam hitungan. Rasakan langkah Anda kini lebih ringan. Lanjutkan ke barat lalu ke utara kembali ke titik start.'),
  ('T01', 5, 'Finish: Titik Start', 'P06', extensions.st_setsrid(extensions.st_makepoint(107.6417524, -6.9152676), 4326)::extensions.geography, 25, 'Pendinginan', 'Selamat, Anda menyelesaikan Rute Santai Kelilingi Danau! Lakukan pendinginan: tarik tumit ke arah bokong untuk meregangkan paha depan, tahan lima belas hitungan untuk setiap kaki. Jangan lupa minum air.');
insert into public.wellness_trail (id, name, subtitle, description, level, distance_m, est_minutes, best_times, color, path, sort_order) values ('T02', 'Jogging Lingkar Kiara Artha', 'Satu putaran jogging di lingkar Jl. Kiara Artha', 'Rute jogging mengikuti lingkar Jl. Kiara Artha yang mengelilingi taman. Panduan audio di tiap sisi taman membantu menjaga ritme langkah dan napas. Ulangi untuk menambah jarak.', 'Sedang', 760, 10, array['pagi', 'sore']::text[], '#ee7b5b', '[[-6.915208,107.641662],[-6.915149,107.641736],[-6.915098,107.641814],[-6.915055,107.641896],[-6.915019,107.64198],[-6.914993,107.642066],[-6.914974,107.642154],[-6.914965,107.642242],[-6.914964,107.642331],[-6.914972,107.642419],[-6.914988,107.642506],[-6.915014,107.642591],[-6.915047,107.642673],[-6.915089,107.642753],[-6.915139,107.642828],[-6.915196,107.642899],[-6.91526,107.642966],[-6.91533,107.643027],[-6.915407,107.643082],[-6.915489,107.64313],[-6.915576,107.643173],[-6.915667,107.643208],[-6.915761,107.643236],[-6.915858,107.643256],[-6.915957,107.643269],[-6.916058,107.643274],[-6.916159,107.643272],[-6.916259,107.643262],[-6.916358,107.643244],[-6.916456,107.643218],[-6.916551,107.643186],[-6.916643,107.643146],[-6.91673,107.643099],[-6.916813,107.643047],[-6.916891,107.642988],[-6.916963,107.642923],[-6.917028,107.642854],[-6.917087,107.64278],[-6.917138,107.642702],[-6.917181,107.64262],[-6.917217,107.642536],[-6.917243,107.64245],[-6.917262,107.642362],[-6.917271,107.642274],[-6.917272,107.642185],[-6.917264,107.642097],[-6.917248,107.64201],[-6.917222,107.641925],[-6.917189,107.641843],[-6.917147,107.641763],[-6.917097,107.641688],[-6.91704,107.641617],[-6.916976,107.64155],[-6.916906,107.641489],[-6.916829,107.641434],[-6.916747,107.641386],[-6.91666,107.641343],[-6.916569,107.641308],[-6.916475,107.64128],[-6.916378,107.64126],[-6.916279,107.641247],[-6.916178,107.641242],[-6.916077,107.641244],[-6.915977,107.641254],[-6.915878,107.641272],[-6.91578,107.641298],[-6.915685,107.64133],[-6.915593,107.64137],[-6.915506,107.641417],[-6.915423,107.641469],[-6.915345,107.641528],[-6.915273,107.641593],[-6.915208,107.641662]]'::jsonb, 2);
insert into public.trail_checkpoint (trail_id, seq, name, poi_id, location, radius_m, exercise, coaching) values
  ('T02', 1, 'Start: Sisi Barat Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.641662, -6.915208), 4326)::extensions.geography, 25, 'Pemanasan dinamis', 'Selamat datang di Jogging Lingkar Kiara Artha. Lakukan pemanasan dinamis: angkat lutut bergantian selama tiga puluh detik. Lalu mulai jogging pelan searah jarum jam.'),
  ('T02', 2, 'Sisi Timur Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.64313, -6.915489), 4326)::extensions.geography, 25, 'Atur ritme napas', 'Checkpoint dua, sisi timur laut. Atur ritme napas: tarik napas dua langkah, hembuskan dua langkah. Anda seharusnya masih bisa berbicara dengan nyaman.'),
  ('T02', 3, 'Sisi Tenggara', null, extensions.st_setsrid(extensions.st_makepoint(107.642854, -6.917028), 4326)::extensions.geography, 25, 'Postur lari', 'Checkpoint tiga, sisi tenggara. Periksa postur: badan tegak sedikit condong ke depan, lengan menekuk sembilan puluh derajat, dan mendarat dengan tengah telapak kaki.'),
  ('T02', 4, 'Sisi Barat Daya', null, extensions.st_setsrid(extensions.st_makepoint(107.641434, -6.916829), 4326)::extensions.geography, 25, 'Jaga kecepatan', 'Checkpoint empat, sisi barat daya. Sedikit lagi! Pertahankan kecepatan yang nyaman. Area kuliner ada di sebelah kanan Anda bila ingin beristirahat setelah ini.'),
  ('T02', 5, 'Finish: Sisi Barat Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.641662, -6.915208), 4326)::extensions.geography, 25, 'Pendinginan', 'Satu putaran selesai, kerja bagus! Berjalanlah pelan selama dua menit untuk pendinginan, lalu regangkan betis dengan bertumpu pada dinding atau pohon.');

